create table lastseen (tenant_id varchar(64) not null, username varchar(128) not null, firstname varchar(255), lastname varchar(255), mail varchar(255), last_seen_timestamp timestamp(6) not null, primary key (tenant_id, username))
create table properties (id varchar(40) not null, create_timestamp timestamp(6), created_by varchar(255), hidden boolean not null, immutable boolean not null, modified_by varchar(255), modify_timestamp timestamp(6), pending_deletion_count int default 0, p_key varchar(255) not null, p_value varchar(2048), primary key (id), unique (p_key))
create table secretdata (id varchar(40) not null, create_timestamp timestamp(6), created_by varchar(255), hidden boolean not null, immutable boolean not null, modified_by varchar(255), modify_timestamp timestamp(6), pending_deletion_count int default 0, checksum varchar(64) not null, description text, s_key varchar(255) not null, name varchar(255), secret text, size bigint not null, type varchar(255) not null check (type in ('SIGNATURE_PAD_JSON','ID_SIGNATURE_JWT','ID_FRONT_IMAGE','ID_BACK_IMAGE','EXT_IDENTIFICATION_STATUS','EXT_IDENTIFICATION_ARCHIVE')), primary key (id))
create table vaultadminkeys (id varchar(40) not null, create_timestamp timestamp(6), created_by varchar(255), hidden boolean not null, immutable boolean not null, modified_by varchar(255), modify_timestamp timestamp(6), pending_deletion_count int default 0, admin_id varchar(255), credential_id varchar(255) not null unique, description varchar(255), encrypted_master_key varchar(255), full_name varchar(255), prf_salt varchar(255), primary key (id))
